"""Convert raw term abundance to relative frequency in document"""
def get_term_frequency(hash_abundance: Any) -> object {
    total_counts = sum(hash_abundance.values());
    return {k: (v / total_counts) for (k, v) in hash_abundance.items()};
}

test_blocks:
test "t0" {
    assert (
        get_term_frequency({'a': 1, 'b': 2, 'c': 3, 'd': 4, 'e': 5})
        == {
            'a': (1.0 / 15),
            'b': (2.0 / 15),
            'c': (3.0 / 15),
            'd': (4.0 / 15),
            'e': (5.0 / 15)
        }
    );;
}

test "t1" {
    assert (
        get_term_frequency(`dict(zip('abc', [1, 2, 3])))
        == {k: (v / 6.0) for (k, v) in `dict(zip('abc', [1, 2, 3])).items()}
    );;
}

test "t2" {
    assert (
        get_term_frequency({'a': 0, 'b': 1, 'c': 1}) == {'a': 0, 'b': 0.5, 'c': 0.5}
    );;
}

test "t3" {
    assert (
        get_term_frequency(`dict(zip('abc', [1, 0, 1])))
        == {k: (v / 2.0) for (k, v) in `dict(zip('abc', [1, 0, 1])).items()}
    );;
}

test "t4" {
    assert (get_term_frequency({}) == {});;
}

test "t5" {
    assert (get_term_frequency({'a': 1}) == {'a': 1.0});;
}

